-- ==============================================================================
-- MIGRACIÓN DEFINITIVA CORREGIDA (Soporta IDs BIGINT y UUID)
-- Tablas objetivo: public.user_love_messages y public.user_love_reactions
-- ==============================================================================

-- 1. Si la tabla public.user_love_messages fue creada como UUID, o no existe:
-- Las tablas históricas en Supabase usan BIGINT GENERATED BY DEFAULT AS IDENTITY para id.
-- Usamos BIGINT GENERATED BY DEFAULT AS IDENTITY para id o permitimos migración exacta.
CREATE TABLE IF NOT EXISTS public.user_love_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    target_user_id TEXT NOT NULL,
    user_uid TEXT NOT NULL,
    author_name TEXT NOT NULL DEFAULT 'Anónimo',
    author_avatar TEXT,
    author_gender TEXT,
    message TEXT NOT NULL,
    hearts_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Si la tabla ya había sido creada con tipo UUID o falta alguna columna, aseguramos compatibilidad:
DO $$
BEGIN
    -- Asegurar columnas author_gender y author_avatar
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'user_love_messages' AND column_name = 'author_gender'
    ) THEN
        ALTER TABLE public.user_love_messages ADD COLUMN author_gender TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'user_love_messages' AND column_name = 'author_avatar'
    ) THEN
        ALTER TABLE public.user_love_messages ADD COLUMN author_avatar TEXT;
    END IF;
END $$;

-- 2. Crear tabla de reacciones / corazones: public.user_love_reactions
-- Soporta tanto si user_love_messages.id es BIGINT como si es UUID o TEXT
CREATE TABLE IF NOT EXISTS public.user_love_reactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    message_id TEXT NOT NULL,
    user_uid TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT user_love_reactions_unique_user UNIQUE (message_id, user_uid)
);

-- 3. Índices de aceleración de consultas
CREATE INDEX IF NOT EXISTS idx_user_love_messages_target 
    ON public.user_love_messages (target_user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_user_love_messages_uid 
    ON public.user_love_messages (user_uid);

CREATE INDEX IF NOT EXISTS idx_user_love_reactions_msg 
    ON public.user_love_reactions (message_id);

CREATE INDEX IF NOT EXISTS idx_user_love_reactions_user 
    ON public.user_love_reactions (user_uid);

-- 4. Habilitar RLS (Seguridad y permisos públicos/autores)
ALTER TABLE public.user_love_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_love_reactions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read love messages" ON public.user_love_messages;
CREATE POLICY "Public read love messages" 
    ON public.user_love_messages FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Public insert love messages" ON public.user_love_messages;
CREATE POLICY "Public insert love messages" 
    ON public.user_love_messages FOR INSERT 
    WITH CHECK (true);

DROP POLICY IF EXISTS "Author delete love messages" ON public.user_love_messages;
CREATE POLICY "Author delete love messages" 
    ON public.user_love_messages FOR DELETE 
    USING (true);

DROP POLICY IF EXISTS "Public update love messages hearts" ON public.user_love_messages;
CREATE POLICY "Public update love messages hearts" 
    ON public.user_love_messages FOR UPDATE 
    USING (true);

DROP POLICY IF EXISTS "Public read love reactions" ON public.user_love_reactions;
CREATE POLICY "Public read love reactions" 
    ON public.user_love_reactions FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Public insert love reactions" ON public.user_love_reactions;
CREATE POLICY "Public insert love reactions" 
    ON public.user_love_reactions FOR INSERT 
    WITH CHECK (true);

DROP POLICY IF EXISTS "Author delete love reactions" ON public.user_love_reactions;
CREATE POLICY "Author delete love reactions" 
    ON public.user_love_reactions FOR DELETE 
    USING (true);

-- 5. MIGRACIÓN DE DATOS (Maneja id tanto si user_love_messages tiene id BIGINT como UUID)
DO $$
DECLARE
    id_data_type text;
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'student_love_messages'
    ) THEN
        -- Detectar el tipo de dato de 'id' en user_love_messages
        SELECT data_type INTO id_data_type
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'user_love_messages' AND column_name = 'id';

        IF id_data_type = 'uuid' THEN
            -- Si la tabla fue creada previamente como UUID, generamos un nuevo UUID para cada fila
            INSERT INTO public.user_love_messages (
                target_user_id,
                user_uid,
                author_name,
                author_avatar,
                author_gender,
                message,
                hearts_count,
                created_at
            )
            SELECT 
                slm.student_id::text, 
                slm.user_uid,
                'Anónimo-' || COALESCE(NULLIF(SUBSTRING(slm.user_uid FROM 1 FOR 8), ''), 'campus'),
                NULL,
                NULL,
                slm.message,
                COALESCE(slm.hearts_count, 0),
                COALESCE(slm.created_at, NOW())
            FROM public.student_love_messages slm;
        ELSE
            -- Si es bigint / integer / serial estándar
            INSERT INTO public.user_love_messages (
                id,
                target_user_id,
                user_uid,
                author_name,
                author_avatar,
                author_gender,
                message,
                hearts_count,
                created_at
            )
            SELECT 
                slm.id,
                slm.student_id::text, 
                slm.user_uid,
                'Anónimo-' || COALESCE(NULLIF(SUBSTRING(slm.user_uid FROM 1 FOR 8), ''), 'campus'),
                NULL,
                NULL,
                slm.message,
                COALESCE(slm.hearts_count, 0),
                COALESCE(slm.created_at, NOW())
            FROM public.student_love_messages slm
            ON CONFLICT (id) DO NOTHING;
        END IF;
    END IF;
END $$;

-- 6. Migrar reacciones previas desde student_love_message_hearts
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'student_love_message_hearts'
    ) THEN
        INSERT INTO public.user_love_reactions (
            message_id,
            user_uid,
            created_at
        )
        SELECT 
            slh.message_id::text,
            slh.user_uid,
            COALESCE(slh.created_at, NOW())
        FROM public.student_love_message_hearts slh
        ON CONFLICT (message_id, user_uid) DO NOTHING;
    END IF;
END $$;

-- 7. Sincronizar el conteo de corazones para exactitud total
UPDATE public.user_love_messages ulm
SET hearts_count = (
    SELECT COUNT(*) 
    FROM public.user_love_reactions ulr 
    WHERE ulr.message_id = ulm.id::text
);
